\n	},\n	Card2 = {\n		accessLevel = 2,\n		name = "Карта уровня 2",\n		openDoors = {"CellDoor", "AdminDoor", "ExperimentDoor"},\n		blockedRooms = {"ControlRoom", "MeetingHall", "ManagerOffice", "DSCOffice"},\n	},\n	Card3 = {\n		accessLevel = 3,\n		name = "Карта уровня 3",\n		openDoors = {"CellDoor", "AdminDoor", "ExperimentDoor"},\n		blockedRooms = {"MeetingHall", "DSCOffice"},\n	},\n	CardFactionBST = {\n		accessLevel = 2,\n		name = "Карта BST",\n		openDoors = {"CellDoor", "AdminDoor", "ExperimentDoor"},\n		blockedRooms = {"MeetingHall", "DSCOffice"},\n		factionLock = "BST",\n	},\n	CardFactionATF = {\n		accessLevel = 2,\n		name = "Карта ATF",\n		openDoors = {"CellDoor", "AdminDoor", "ExperimentDoor"},\n		blockedRooms = {"MeetingHall", "DSCOffice"},\n		factionLock = "ATF",\n	},\n	CardFactionSnezhok = {\n		accessLevel = 2,\n		name = "Карта Snezhok",\n		openDoors = {"CellDoor", "AdminDoor", "ExperimentDoor"},\n		blockedRooms = {"MeetingHall", "DSCOffice"},\n		factionLock = "Snezhok",\n	},\n	CardFactionGDF = {\n		accessLevel = 2,\n		name = "Карта G.D.F.",\n		openDoors = {"CellDoor", "AdminDoor", "ExperimentDoor"},\n		blockedRooms = {"MeetingHall", "DSCOffice"},\n		factionLock = "GDF",\n	},\n	CardFactionRaider = {\n		accessLevel = 2,\n		name = "Карта Рейдеров",\n		openDoors = {"CellDoor", "AdminDoor", "ExperimentDoor"},\n		blockedRooms = {"MeetingHall", "DSCOffice"},\n		factionLock = "Raider",\n	},\n}\n\nConfig.DoorTypes = {\n	Regular = {\n		openAngle = 90,\n		openSpeed = 1,\n		animationType = "swing",\n	},\n	Armored = {\n		openOffset = Vector3.new(0, 6, 0),\n		openSpeed = 2,\n		animationType = "slide_up",\n	},\n	Hermetic = {\n		openOffset = Vector3.new(0, 8, 0),\n		openSpeed = 0.5,\n		animationType = "slide_up",\n	},\n}\n\nConfig.DShopItems = {\n	{weaponId = "Pistol", price = 100},\n	{weaponId = "Knife", price = 50},\n	{weaponId = "Shotgun", price = 250},\n}\n\nConfig.DoctorShopItems = {\n	{itemId = "Medkit", price = 75},\n	{itemId = "Adrenaline", price = 100},\n}\n\nConf